  final String name;

  /// Creates a new [GetTenantResult].
  /// [externalId] Client side tenant identifier, used to uniquely identify the tenant. The maximum number of allowed characters is 255.
  /// [name] Required during tenant update. The resource name for a tenant. This is generated by the service when a tenant is created. The format is "projects/{project_id}/tenants/{tenant_id}", for example, "projects/foo/tenants/bar".
  const GetTenantResult({
    required this.externalId,
    required this.name,
  });

  Map<String, dynamic> toMap() {
    return <String, dynamic>{
      'externalId': externalId,
      'name': name,
    };
  }

  factory GetTenantResult.fromMap(Map<String, dynamic> map) {
    return GetTenantResult(
      externalId: map['externalId'] as String,
      name: map['name'] as String,
    );
  }
}
